export const AIRCRAFT=[{name:'雨燕号',subtitle:'平衡型 · 可靠的第一位伙伴',hp:100,speed:115,rate:.14,color:0xefab55,cost:0},{name:'游隼号',subtitle:'敏捷型 · 为追风而生',hp:80,speed:141,rate:.115,color:0x52a5a5,cost:700},{name:'信天翁号',subtitle:'重装型 · 天空中的守护者',hp:145,speed:99,rate:.17,color:0xdb7561,cost:1100}];
export const UPGRADES=[{id:'gun',icon:'✹',name:'双翼火力',text:'机枪伤害提升 35%，让每次命中更有分量。',tag:'火力强化'},{id:'spread',icon:'⋔',name:'羽翼散射',text:'增加两条斜向弹道，覆盖更宽的攻击区域。',tag:'武器改造'},{id:'armor',icon:'⬡',name:'轻量装甲',text:'最大生命增加 30，并立即修复 50 点生命。',tag:'生存保障'},{id:'missile',icon:'↟',name:'蜂鸟导弹',text:'补充 6 枚导弹，导弹伤害提升 30%。',tag:'精确打击'},{id:'engine',icon:'ϟ',name:'顺风引擎',text:'巡航速度提升 12%，加速能量恢复更快。',tag:'飞行性能'},{id:'shield',icon:'◈',name:'云朵护盾',text:'护盾上限增加 35，立刻充满护盾。',tag:'防御升级'},{id:'repair',icon:'✚',name:'燕巢维修包',text:'生命完全恢复，每次翻滚额外修复 8 点。',tag:'维修支援'},{id:'rapid',icon:'≋',name:'疾风机炮',text:'射速提升 25%，弹丸飞得更快。',tag:'火力强化'}];
class AudioEngine{constructor(){this.enabled=true;this.ctx=null;this.engine=null;this.last=0;}init(){if(this.ctx){this.ctx.resume().catch(()=>{});return;}try{this.ctx=new(window.AudioContext||window.webkitAudioContext)();const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type='sawtooth';o.frequency.value=53;g.gain.value=.009;o.connect(g);g.connect(this.ctx.destination);o.start();this.engine={o,g};}catch{}}tone(freq,duration=.1,type='sine',volume=.05,to=0){if(!this.enabled||!this.ctx)return;const t=this.ctx.currentTime,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);if(to)o.frequency.exponentialRampToValueAtTime(Math.max(20,to),t+duration);g.gain.setValueAtTime(volume,t);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(this.ctx.destination);o.start(t);o.stop(t+duration);}play(name){if(name==='shot'){if(performance.now()-this.last<100)return;this.last=performance.now();this.tone(350,.07,'square',.009,100);}if(name==='hit')this.tone(130,.09,'triangle',.08,50);if(name==='boom'){this.tone(80,.5,'sawtooth',.09,23);this.tone(54,.7,'triangle',.09,20);}if(name==='pickup'){this.tone(680,.2,'sine',.07,1000);setTimeout(()=>this.tone(1080,.2,'sine',.05,1500),100);}if(name==='missile')this.tone(160,.5,'sawtooth',.04,750);if(name==='roll')this.tone(300,.3,'sine',.05,900);if(name==='alert')this.tone(300,.2,'square',.02,260);}update(boost,active){if(this.engine){this.engine.g.gain.setTargetAtTime(this.enabled?(active?.012:.003):0,this.ctx.currentTime,.2);this.engine.o.frequency.setTargetAtTime(boost?88:52,this.ctx.currentTime,.2);}}}
export class FlightGame extends EventTarget{
 constructor(canvas){super();this.canvas=canvas;this.renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));this.renderer.setSize(innerWidth,innerHeight);this.renderer.outputColorSpace=THREE.SRGBColorSpace;this.renderer.toneMapping=THREE.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.03;this.scene=new THREE.Scene();this.scene.background=new THREE.Color(0xb8e0e4);this.scene.fog=new THREE.Fog(0xb8e0e4,1100,3900);this.camera=new THREE.PerspectiveCamera(57,innerWidth/innerHeight,1,6500);this.clock=new THREE.Clock();this.mode='menu';this.time=0;this.keys={};this.pointer={x:0,y:0,active:false};this.touch={x:0,y:0,fire:false,boost:false};this.control='keyboard';this.audio=new AudioEngine();this.enemies=[];this.bullets=[];this.particles=[];this.pickups=[];this.rings=[];this.clouds=[];this.world=[];this.events=[];this.shake=0;this.selected=0;this.menuTime=0;this.autoFire=false;this.temp=new V();this.forward=new V();this.up=new V(0,1,0);this.stats={};this.target=null;this.lockTime=0;this.pausedFrom=null;this.makeMaterials();this.makeWorld();this.player=this.makePlane(AIRCRAFT[0].color,true);this.scene.add(this.player);this.setupInput();this.resize=()=>{this.camera.aspect=innerWidth/innerHeight;this.camera.updateProjectionMatrix();this.renderer.setSize(innerWidth,innerHeight);};addEventListener('resize',this.resize);this.loop();}
 emit(name,detail={}){this.dispatchEvent(new CustomEvent(name,{detail}));}
 makeMaterials(){this.mats={};const colors={cream:0xffefd0,navy:0x214352,orange:0xe88047,white:0xfff9e9,red:0xb34e40,gold:0xffce76,metal:0x5f7174,green:0x7cba83,grass:0x95c795,rock:0x867a67,dark:0x252f3c};for(const [k,v]of Object.entries(colors))this.mats[k]=new THREE.MeshStandardMaterial({color:v,roughness:.75,flatShading:true});this.geos={sphere:new THREE.IcosahedronGeometry(1,1),box:new THREE.BoxGeometry(1,1,1),cylinder:new THREE.CylinderGeometry(1,1,1,12),cone:new THREE.ConeGeometry(1,1,8)};}
 mesh(geo,mat,scale,pos,parent){const m=new THREE.Mesh(typeof geo==='string'?this.geos[geo]:geo,typeof mat==='string'?this.mats[mat]:mat);if(scale)m.scale.set(...scale);if(pos)m.position.set(...pos);if(parent)parent.add(m);return m;}
 makePlane(color=0xeaa658,pilot=false,enemyType=0){const g=new THREE.Group();const paint=new THREE.MeshStandardMaterial({color,roughness:.65,metalness:.06,flatShading:true});g.userData.paint=paint;this.mesh('sphere',paint,[3.7,3.3,11.8],[0,0,0],g);this.mesh('sphere','cream',[2.6,2.5,7],[0,-.8,0],g);this.mesh('box',paint,[27,.7,5],[0,.7,0],g);this.mesh('box',paint,[26,.65,5],[0,5.3,-1],g);for(const x of[-10,10]){this.mesh('box','cream',[2,.76,5.1],[x,.7,0],g);this.mesh('box','cream',[2,.72,5.1],[x,5.3,-1],g);for(const z of[-2,1]){const s=this.mesh('cylinder','metal',[.16,4.4,.16],[x,3,z],g);s.rotation.z=x*.013;}}this.mesh('box',paint,[11,.6,3.1],[0,1.5,8.7],g);this.mesh('sphere',paint,[.55,3.5,3.2],[0,2.2,8.1],g);this.mesh('sphere','navy',[3,2.4,2.2],[0,0,-9.2],g);this.mesh('sphere','metal',[1.1,1.1,1.8],[0,0,-11.2],g);const prop=new THREE.Group();prop.position.set(0,0,-12.5);this.mesh('box','dark',[.7,12,.35],[0,0,0],prop);this.mesh('sphere','gold',[.9,.9,.65],[0,0,-.3],prop);g.add(prop);g.userData.prop=prop;for(const x of[-2.8,2.8]){this.mesh('box','metal',[.2,3,.3],[x,-3.3,0],g);const wheel=this.mesh('cylinder','dark',[1.3,.65,1.3],[x,-4.4,0],g);wheel.rotation.z=Math.PI/2;}
 const cockpit=this.mesh('sphere','navy',[2.6,.7,3],[0,2.8,3],g);if(pilot){const bird=new THREE.Group();bird.position.set(0,4.2,3.5);this.mesh('sphere','navy',[1.9,2.7,1.8],[0,0,0],bird);this.mesh('sphere','cream',[1.45,1.9,1.2],[0,0,-.8],bird);this.mesh('sphere','navy',[2.15,1.95,2.1],[0,2.5,-.2],bird);this.mesh('sphere','cream',[1.8,1.25,1.4],[0,1.9,-1.1],bird);const beak=this.mesh('cone','gold',[.8,2,.7],[0,2.1,-2.6],bird);beak.rotation.x=-Math.PI/2;for(const x of[-1.25,1.25]){this.mesh('sphere','metal',[.94,.9,.5],[x,2.9,-1.6],bird);this.mesh('sphere','dark',[.65,.6,.5],[x,3,-1.88],bird);this.mesh('sphere','white',[.2,.2,.16],[x-.1,3.2,-2.25],bird);}this.mesh('box','red',[3.8,.7,3],[0,.9,0],bird);const scarf=this.mesh('box','red',[1.2,.3,5],[1.7,1.2,2.7],bird);scarf.rotation.y=-.3;g.userData.scarf=scarf;for(const x of[-.5,.5]){const tail=this.mesh('cone','navy',[.5,4,.3],[x,-1,2],bird);tail.rotation.x=-2.2;tail.rotation.z=x*.5;}g.add(bird);const windshield=this.mesh(new THREE.SphereGeometry(2.2,12,8,0,Math.PI,0,Math.PI/2),new THREE.MeshStandardMaterial({color:0xbfe3df,transparent:true,opacity:.5,roughness:.1}),[1,1,1],[0,3,1.5],g);windshield.rotation.y=Math.PI;}else{this.mesh('sphere','dark',[1.8,1.6,1.7],[0,4,3],g);const flag=this.mesh('box','dark',[5,3,.12],[0,7,6],g);this.mesh('sphere','white',[.9,.85,.15],[0,7.3,5.9],g);this.mesh('box','white',[2.5,.25,.17],[0,6.3,5.9],g);if(enemyType===1){g.scale.setScalar(.83);this.mesh('box','red',[32,.6,3],[0,1,-1],g);}if(enemyType===2){g.scale.setScalar(1.25);this.mesh('sphere','dark',[2,2,6],[-8,-1,0],g);this.mesh('sphere','dark',[2,2,6],[8,-1,0],g);}}
 return g;}
 makeBoss(){const g=new THREE.Group();this.mesh('sphere','dark',[28,25,76],[0,7,0],g);this.mesh('sphere','red',[28.5,25.5,24],[0,7,-15],g);this.mesh('sphere','cream',[23,20,17],[0,7,-61],g);this.mesh('box','rock',[20,9,42],[0,-23,3],g);this.mesh('box','gold',[21,1,43],[0,-18,3],g);for(const x of[-31,31]){this.mesh('box','red',[31,2,17],[x,1,10],g);this.mesh('sphere','metal',[7,7,15],[x,-5,-10],g);this.mesh('box','cream',[2,24,3],[x,-5,-27],g);}this.mesh('box','red',[53,1.4,23],[0,10,57],g);this.mesh('box','red',[1.4,29,23],[0,25,55],g);this.mesh('sphere','white',[10,9,1],[0,13,-76],g);for(const x of[-3.5,3.5])this.mesh('sphere','dark',[2,3,1],[x,14,-76.8],g);for(const rot of[-.5,.5]){const bone=this.mesh('box','white',[24,2,1],[0,-2,-76.8],g);bone.rotation.z=rot;}g.userData.boss=true;return g;}
 makeWorld(){this.scene.add(new THREE.HemisphereLight(0xecffff,0x497b7e,1.9));const sun=new THREE.DirectionalLight(0xffedcb,2.7);sun.position.set(-400,900,600);this.scene.add(sun);const oceanGeo=new THREE.PlaneGeometry(15000,15000,1,1);const oceanMat=new THREE.ShaderMaterial({uniforms:{uTime:{value:0},uColor:{value:new THREE.Color(0x4eafbd)},uFar:{value:new THREE.Color(0xb8e0e4)}},vertexShader:'varying vec3 vWorld; void main(){vec4 w=modelMatrix*vec4(position,1.);vWorld=w.xyz;gl_Position=projectionMatrix*viewMatrix*w;}',fragmentShader:'uniform float uTime;uniform vec3 uColor;uniform vec3 uFar;varying vec3 vWorld;void main(){float a=sin(vWorld.x*.055+uTime*.38+sin(vWorld.z*.028))*sin(vWorld.z*.04-uTime*.21);float foam=smoothstep(.86,.96,a)*.16;vec3 col=uColor+vec3(foam);float far=smoothstep(400.,4600.,distance(cameraPosition.xz,vWorld.xz));gl_FragColor=vec4(mix(col,uFar,far),1.);}'});const sea=new THREE.Mesh(oceanGeo,oceanMat);sea.rotation.x=-Math.PI/2;sea.position.y=-85;this.scene.add(sea);this.sea=sea;
 const locations=[[-250,-400,120],[-700,-700,210],[620,-620,150],[1000,70,250],[-950,600,190],[350,880,280],[-140,1600,200],[1450,-1300,270],[-1500,-1800,260],[1650,1500,210],[-1800,1700,280],[200,-2300,250]];for(let i=0;i<locations.length;i++){const[x,z,r]=locations[i],g=new THREE.Group(),top=i===0?-20:rand(-42,15);g.position.set(x,top,z);this.mesh(new THREE.CylinderGeometry(r,r*.4,130,7), 'rock',[1,1,1],[0,-65,0],g);this.mesh('sphere','grass',[r,17,r*.86],[0,-2,0],g);this.mesh(new THREE.CylinderGeometry(r*1.03,r*.96,7,12),'cream',[1,1,1],[0,-10,0],g);for(let j=0;j<6;j++){const a=j*2.39,rr=r*.6*Math.sqrt((j+1)/6),tx=Math.cos(a)*rr,tz=Math.sin(a)*rr,h=rand(23,40);this.mesh('cylinder','rock',[2,h,2],[tx,h/2,tz],g);this.mesh('cone','green',[14,h*.9,14],[tx,h+6,tz],g);this.mesh('cone','grass',[10,h*.75,10],[tx,h+17,tz],g);}if(i===0||i===3){const lighthouse=new THREE.Group();this.mesh('cylinder','cream',[9,50,9],[0,25,0],lighthouse);this.mesh('cylinder','red',[9.2,10,9.2],[0,25,0],lighthouse);this.mesh('cylinder','navy',[11,10,11],[0,54,0],lighthouse);this.mesh('cone','orange',[15,13,15],[0,64,0],lighthouse);this.mesh('sphere','gold',[6,5,6],[0,55,0],lighthouse);lighthouse.position.set(0,10,0);g.add(lighthouse);}this.scene.add(g);this.world.push({x,z,r:r*.8,top:top+20});}
 for(let i=0;i<38;i++){const g=new THREE.Group();for(let j=0;j<4;j++)this.mesh('sphere','white',[rand(40,80),rand(20,40),rand(35,65)],[(j-1.5)*48,rand(-8,8),rand(-20,20)],g);g.position.set(rand(-3200,3200),rand(310,630),rand(-3200,3200));g.rotation.y=rand(0,6);this.scene.add(g);this.clouds.push(g);}const sunBall=this.mesh('sphere',new THREE.MeshBasicMaterial({color:0xffe9b1}),[170,170,170],[-2500,1400,-3300],this.scene);}
 selectPlane(i){this.selected=i;this.scene.remove(this.player);this.disposePlane(this.player);this.player=this.makePlane(AIRCRAFT[i].color,true);this.scene.add(this.player);}
 disposePlane(p){p.traverse(o=>{if(o.isMesh){if(!Object.values(this.geos).includes(o.geometry))o.geometry.dispose();if(!Object.values(this.mats).includes(o.material))o.material.dispose();}});}
 setupInput(){addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement)return;if(this.mode==='playing'&&['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();this.keys[e.code]=true;if(e.repeat)return;if(e.code==='KeyP'||e.code==='Escape'){if(this.mode==='playing')this.pause();else if(this.mode==='paused')this.resume();}if(e.code==='KeyE')this.missile();if(e.code==='KeyQ')this.roll();if(e.code==='KeyX'){this.autoFire=!this.autoFire;this.emit('autofire');}if(e.code==='KeyM')this.emit('soundtoggle');});addEventListener('keyup',e=>{this.keys[e.code]=false;});addEventListener('blur',()=>{this.clearInput();if(this.mode==='playing')this.pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){this.clearInput();if(this.mode==='playing')this.pause();}});this.canvas.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;this.pointer.x=clamp((e.clientX/innerWidth-.5)*2,-1,1);this.pointer.y=clamp((e.clientY/innerHeight-.5)*2,-1,1);this.pointer.active=true;});this.canvas.addEventListener('pointerdown',e=>{if(this.mode==='playing'&&e.button===0){this.keys.Mouse=true;this.audio.init();}});addEventListener('pointerup',()=>{this.keys.Mouse=false;});this.canvas.addEventListener('pointerleave',()=>{this.pointer.active=false;this.keys.Mouse=false;});this.canvas.addEventListener('contextmenu',e=>e.preventDefault());}
 clearInput(){this.keys={};this.touch={x:0,y:0,fire:false,boost:false};this.pointer.active=false;}
 start(difficulty='adventure'){this.clearCombat();this.clearInput();const a=AIRCRAFT[this.selected];this.difficulty=difficulty;this.player.scale.setScalar(1);this.player.position.set(0,135,120);this.yaw=0;this.pitch=0;this.bank=0;this.player.rotation.set(0,0,0);this.speed=a.speed;this.baseSpeed=a.speed;this.maxHp=a.hp;this.hp=a.hp;this.maxShield=45;this.shield=45;this.boost=100;this.boostRegen=18;this.gunDamage=20;this.fireRate=a.rate;this.spread=0;this.missileDamage=110;this.missiles=5;this.rollCooldown=0;this.rollTime=0;this.repairRoll=false;this.fireCooldown=0;this.missileCooldown=0;this.invincible=2;this.damageTimer=0;this.score=0;this.combo=0;this.comboTimer=0;this.wave=0;this.ringTotal=0;this.kills=0;this.runTime=0;this.runCoins=0;this.endless=false;this.stats={shots:0,hits:0,rolls:0,damage:0,missileKills:0,boostTime:0,maxCombo:0};this.mode='playing';this.autoFire=false;this.camera.position.copy(this.player.position).add(new V(0,25,85));this.audio.init();this.nextWave();this.emit('start');}
 clearCombat(){for(const list of[this.enemies,this.bullets,this.particles,this.pickups,this.rings]){for(const item of list){this.scene.remove(item.mesh);if(item.owned){item.mesh.geometry?.dispose();item.mesh.material?.dispose();}else if(list===this.particles){item.mesh.material?.dispose();}if(list===this.enemies)this.disposePlane(item.mesh);}list.length=0;}this.target=null;this.lockTime=0;}
 menu(){this.mode='menu';this.clearCombat();this.clearInput();this.emit('menu');}
 pause(){if(this.mode!=='playing')return;this.mode='paused';this.clearInput();this.emit('pause');}
 resume(){if(this.mode!=='paused')return;this.mode='playing';this.clearInput();this.emit('resume');}
 nextWave(){this.wave++;this.waveKills=0;this.transition=0;this.target=null;this.lockTime=0;for(const b of this.bullets)this.scene.remove(b.mesh);this.bullets=[];const boss=this.wave%5===0;this.waveTotal=boss?1:Math.min(3+this.wave,10);this.waveBoss=boss;this.bannerTimer=3.8;this.shield=Math.min(this.maxShield,this.shield+20);this.missiles+=this.wave>1?2:0;const f=this.getForward();const right=new V(-f.z,0,f.x);for(let i=0;i<this.waveTotal;i++){const pos=this.player.position.clone().addScaledVector(f,rand(370,640)).addScaledVector(right,(i-(this.waveTotal-1)/2)*105);pos.y=clamp(this.player.position.y+rand(-55,90),80,440);this.spawnEnemy(pos,boss?3:(this.wave<2?0:i%3));}this.spawnRings();this.emit('wave',{wave:this.wave,boss,total:this.waveTotal});}
 spawnEnemy(pos,type){const boss=type===3,mesh=boss?this.makeBoss():this.makePlane([0x9c5146,0x60607b,0x857450][type],false,type);mesh.position.copy(pos);mesh.rotation.y=this.yaw+Math.PI;this.scene.add(mesh);const health=boss?1750+(Math.floor(this.wave/5)-1)*700:[80,60,145][type]+this.wave*8;this.enemies.push({mesh,type,hp:health,maxHp:health,velocity:new V(),yaw:this.yaw+Math.PI,phase:rand(0,6.28),shoot:rand(2,5),radius:boss?39:13,age:0,hit:0,attackPhase:0});}
 spawnRings(){for(const r of this.rings){this.scene.remove(r.mesh);r.mesh.geometry.dispose();r.mesh.material.dispose();}this.rings=[];this.waveRings=0;const f=this.getForward(),right=new V(-f.z,0,f.x);for(let i=0;i<3;i++){const m=new THREE.Mesh(new THREE.TorusGeometry(27,1.4,8,36),new THREE.MeshStandardMaterial({color:0xffca69,emissive:0xf8af38,emissiveIntensity:.35,roughness:.4}));m.position.copy(this.player.position).addScaledVector(f,180+i*180).addScaledVector(right,Math.sin(i*1.5)*100);m.position.y=clamp(this.player.position.y+(i-1)*30,70,420);m.rotation.y=this.yaw;this.scene.add(m);this.rings.push({mesh:m,owned:true});}}
 getForward(){return new V(-Math.sin(this.yaw)*Math.cos(this.pitch),Math.sin(this.pitch),-Math.cos(this.yaw)*Math.cos(this.pitch));}
 shoot(){if(this.fireCooldown>0||this.mode!=='playing')return;this.fireCooldown=this.fireRate;this.stats.shots++;this.audio.play('shot');const forward=this.getForward();const aim=this.target&&this.lockTime>.15?this.target.mesh.position.clone().addScaledVector(this.target.velocity,.27).sub(this.player.position).normalize():forward;for(const side of[-1,1]){const origin=new V(side*8,.5,-5).applyQuaternion(this.player.quaternion).add(this.player.position);this.addBullet(origin,aim,false,this.gunDamage,false);}if(this.spread){const right=new V(-forward.z,0,forward.x);for(const side of[-1,1])this.addBullet(this.player.position.clone(),aim.clone().addScaledVector(right,side*.07).normalize(),false,this.gunDamage*.65,false);} }
 addBullet(pos,dir,enemy=false,damage=10,missile=false,target=null){const mat=new THREE.MeshBasicMaterial({color:missile?0xffebaa:enemy?0xfa744d:0xfff1b8});const mesh=this.mesh(missile?new THREE.ConeGeometry(1.4,7,5):new THREE.CylinderGeometry(enemy?1.25:.7,enemy?1.25:.7,enemy?9:13,5),mat,[1,1,1],null,this.scene);mesh.position.copy(pos);mesh.quaternion.setFromUnitVectors(this.up,dir);this.bullets.push({mesh,velocity:dir.clone().multiplyScalar(missile?260:enemy?175:630),enemy,damage,missile,target,life:missile?7:enemy?5:1.8,owned:true,age:0,old:pos.clone()});}
 missile(){if(this.mode!=='playing')return;if(this.missileCooldown>0)return;if(this.missiles<=0){this.emit('toast',{text:'导弹已用完，寻找空中补给'});return;}if(!this.target||this.target.hp<=0||!this.enemies.includes(this.target)||this.lockTime<.45){this.emit('toast',{text:'让敌机进入准星，锁定后发射'});return;}this.missiles--;this.missileCooldown=.65;this.audio.play('missile');this.addBullet(this.player.position.clone().add(new V(0,-3,0)),this.getForward(),false,this.missileDamage,true,this.target);this.emit('missile');}
 roll(){if(this.mode!=='playing'||this.rollCooldown>0)return;this.rollTime=.9;this.rollCooldown=this.repairRoll?4:5;this.invincible=1.15;this.stats.rolls++;if(this.repairRoll)this.hp=Math.min(this.maxHp,this.hp+8);this.audio.play('roll');this.emit('toast',{text:'燕返！短暂无敌'});}
 damage(amount){if(this.invincible>0||this.mode!=='playing')return;const real=amount*(this.difficulty==='adventure'?.62:1);this.stats.damage+=real;const absorb=Math.min(this.shield,real);this.shield-=absorb;this.hp-=real-absorb;this.invincible=.65;this.damageTimer=5;this.shake=.7;this.audio.play('hit');this.emit('damage');if(this.hp<=0){this.hp=0;this.explode(this.player.position,0xe79d4b,25);this.finish(false);}}
 explode(pos,color=0xf2a550,count=14){const mat=new THREE.MeshBasicMaterial({color,transparent:true});for(let i=0;i<count;i++){const mesh=this.mesh('sphere',mat.clone(),[rand(1,3),rand(1,3),rand(1,3)],null,this.scene);mesh.position.copy(pos);this.particles.push({mesh,velocity:new V(rand(-50,50),rand(-30,50),rand(-50,50)),life:rand(.4,1.1),max:1.1,owned:false});}mat.dispose();}
 hitEnemy(e,damage,missile=false){if(e.hp<=0)return;e.hp-=damage;this.stats.hits++;e.hit=.12;this.explode(e.mesh.position,0xffd084,missile?10:2);if(e.hp<=0){this.kills++;this.waveKills++;this.combo=this.comboTimer>0?this.combo+1:1;this.comboTimer=8;this.stats.maxCombo=Math.max(this.stats.maxCombo,this.combo);const points=(e.type===3?2400:[180,230,300][e.type])*Math.min(4,1+(this.combo-1)*.25);this.score+=Math.round(points);this.runCoins+=e.type===3?300:30;if(missile)this.stats.missileKills++;this.explode(e.mesh.position,0xec955a,e.type===3?45:20);this.audio.play('boom');this.shake=.4;this.spawnPickup(e.mesh.position.clone(),Math.random()<.34?'health':Math.random()<.5?'missile':'shield');this.emit('kill',{type:e.type,points:Math.round(points)});}}
 spawnPickup(pos,type){const color={health:0x86d098,missile:0xffc366,shield:0x81dbef}[type];const mat=new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:.4,roughness:.3});const mesh=this.mesh(new THREE.OctahedronGeometry(5),mat,[1,1,1],null,this.scene);mesh.position.copy(pos);this.pickups.push({mesh,type,life:45,owned:true});}
 upgrade(id){if(this.mode!=='upgrade')return;const u=UPGRADES.find(x=>x.id===id);if(!u)return;switch(id){case'gun':this.gunDamage*=1.35;break;case'spread':this.spread++;this.gunDamage*=this.spread>1?1.2:1;break;case'armor':this.maxHp+=30;this.hp=Math.min(this.maxHp,this.hp+50);break;case'missile':this.missiles+=6;this.missileDamage*=1.3;break;case'engine':this.baseSpeed*=1.12;this.boostRegen+=8;break;case'shield':this.maxShield+=35;this.shield=this.maxShield;break;case'repair':this.hp=this.maxHp;this.repairRoll=true;break;case'rapid':this.fireRate=Math.max(.055,this.fireRate*.8);break;}this.mode='playing';this.clearInput();this.emit('upgraded',{name:u.name});this.nextWave();}
 finish(won){if(this.mode!=='playing')return;this.mode=won?'victory':'gameover';this.clearInput();this.emit('finish',{won,score:this.score,kills:this.kills,wave:this.wave,rings:this.ringTotal,coins:this.runCoins,stats:{...this.stats},time:this.runTime});}
 continueEndless(){if(this.mode!=='victory')return;this.endless=true;this.mode='playing';this.hp=this.maxHp;this.shield=this.maxShield;this.missiles+=5;this.runCoins=0;this.emit('resume');this.nextWave();}
 tickPlayer(dt){const k=this.keys;let x=(k.KeyD||k.ArrowRight?1:0)-(k.KeyA||k.ArrowLeft?1:0),y=(k.KeyW||k.ArrowUp?1:0)-(k.KeyS||k.ArrowDown?1:0);if(this.control==='mouse'&&this.pointer.active&&!x&&!y){x=Math.abs(this.pointer.x)>.06?this.pointer.x:0;y=Math.abs(this.pointer.y)>.06?-this.pointer.y:0;}if(this.touch.x||this.touch.y){x=this.touch.x;y=-this.touch.y;}this.yaw-=x*dt*1.33;this.pitch=lerp(this.pitch,y*.52,1-Math.exp(-dt*3));this.bank=lerp(this.bank,-x*.72,1-Math.exp(-dt*5));const boost=(k.ShiftLeft||k.ShiftRight||this.touch.boost)&&this.boost>1;this.boost=clamp(this.boost+(boost?-36:this.boostRegen)*dt,0,100);if(boost)this.stats.boostTime+=dt;this.speed=lerp(this.speed,this.baseSpeed*(boost?1.8:1),dt*3);const f=this.getForward();this.player.position.addScaledVector(f,this.speed*dt);const p=this.player.position;if(p.y<22){p.y=22;this.pitch=Math.max(0,this.pitch);this.damage(18);this.emit('radio',{text:'离海面太近！拉高机头。'});}if(p.y>570){p.y=570;this.pitch=Math.min(0,this.pitch);}const distance=Math.hypot(p.x,p.z);if(distance>2400){const desired=Math.atan2(p.x,p.z);const angle=Math.atan2(Math.sin(desired-this.yaw),Math.cos(desired-this.yaw));this.yaw+=clamp(angle,-dt*1.5,dt*1.5);this.emit('boundary',{text:'即将离开空域，正在引导返航'});}let roll=0;if(this.rollTime>0){this.rollTime-=dt;roll=(1-Math.max(0,this.rollTime)/.9)*Math.PI*2;}this.player.rotation.set(this.pitch,this.yaw,this.bank+roll,'YXZ');this.player.visible=this.invincible>.1?Math.sin(this.time*35)>.05:true;if(this.rollTime>0)this.player.visible=true;this.player.userData.prop.rotation.z+=dt*(boost?95:60);if(this.player.userData.scarf)this.player.userData.scarf.rotation.x=Math.sin(this.time*20)*.2;for(const island of this.world){if(Math.hypot(p.x-island.x,p.z-island.z)<island.r&&p.y<island.top+18){this.damage(22);p.y=island.top+19;this.pitch=.2;}}
 this.fireCooldown=Math.max(0,this.fireCooldown-dt);this.missileCooldown=Math.max(0,this.missileCooldown-dt);this.rollCooldown=Math.max(0,this.rollCooldown-dt);this.invincible=Math.max(0,this.invincible-dt);this.damageTimer=Math.max(0,this.damageTimer-dt);if(!this.damageTimer)this.shield=Math.min(this.maxShield,this.shield+dt*3);this.updateTarget(dt);if(this.keys.Space||this.keys.Mouse||this.touch.fire||(this.autoFire&&this.target))this.shoot();this.audio.update(boost,true);
 const behind=f.clone().multiplyScalar(-79).add(new V(0,23,0));const desired=p.clone().add(behind);this.camera.position.lerp(desired,1-Math.exp(-dt*5));const look=p.clone().addScaledVector(f,190).add(new V(0,5,0));this.camera.lookAt(look);this.camera.rotateZ(this.bank*.12);this.camera.fov=lerp(this.camera.fov,boost?66:57,dt*3);this.camera.updateProjectionMatrix();if(this.shake>0){this.camera.position.x+=rand(-this.shake,this.shake);this.camera.position.y+=rand(-this.shake,this.shake);this.shake=Math.max(0,this.shake-dt*2);}if(boost&&Math.random()<.5)this.trail(p.clone().addScaledVector(f,-10),0xffeac1);}
 trail(pos,color){if(this.particles.length>180)return;const mesh=this.mesh('sphere',new THREE.MeshBasicMaterial({color,transparent:true,opacity:.55}),[1.3,1.3,1.3],null,this.scene);mesh.position.copy(pos);this.particles.push({mesh,velocity:new V(0,1,0),life:.55,max:.55});}
 updateTarget(dt){const f=this.getForward();let best=null,bestScore=-Infinity;for(const e of this.enemies){if(e.hp<=0)continue;const d=e.mesh.position.clone().sub(this.player.position),dist=d.length(),dot=d.normalize().dot(f);if(dot>.935&&dist<950){const score=dot-dist*.000025;if(score>bestScore){bestScore=score;best=e;}}}if(best!==this.target){this.target=best;this.lockTime=0;}else if(best)this.lockTime+=dt;}
 tickEnemies(dt){const pp=this.player.position;for(const e of this.enemies){if(e.hp<=0)continue;e.age+=dt;e.shoot-=dt;e.hit=Math.max(0,e.hit-dt);const p=e.mesh.position,delta=pp.clone().sub(p),dist=delta.length();if(e.type===3){const heading=Math.atan2(-delta.x,-delta.z);e.yaw+=Math.atan2(Math.sin(heading-e.yaw),Math.cos(heading-e.yaw))*dt*.3;e.velocity.set(-Math.sin(e.yaw)*40,Math.sin(this.time*.4)*8,-Math.cos(e.yaw)*40);e.attackPhase=Math.floor(e.age/9)%2;e.mesh.rotation.set(Math.sin(this.time*.2)*.04,e.yaw,Math.sin(this.time*.3)*.05);if(e.shoot<0&&dist<1600){e.shoot=e.attackPhase?.7:1.6;const aim=pp.clone().addScaledVector(this.getForward(),this.speed*.6).sub(p).normalize();for(let i=-2;i<=2;i++){const d=aim.clone().add(new V(i*.075,Math.abs(i)*.02,0)).normalize();this.addBullet(p.clone().add(new V(0,-20,-20)),d,true,18);}if(e.age>12&&this.enemies.filter(x=>x.type!==3&&x.hp>0).length<2&&e.attackPhase===1){this.spawnEnemy(p.clone().add(new V(75,-25,0)),1);this.emit('radio',{text:'舰长放出了护航机！优先锁定飞艇。'});}}}else{const orbit=new V(Math.cos(e.age*.55+e.phase)*130,Math.sin(e.age*.8+e.phase)*55,Math.sin(e.age*.55+e.phase)*130);const goal=pp.clone().add(orbit);if(dist<115)goal.addScaledVector(this.getForward(),-230);const aim=goal.sub(p);let heading=Math.atan2(-aim.x,-aim.z);e.yaw+=clamp(Math.atan2(Math.sin(heading-e.yaw),Math.cos(heading-e.yaw)),-dt*(e.type===1?1.3:.8),dt*(e.type===1?1.3:.8));const spd=e.type===1?120:e.type===2?71:92;e.velocity.set(-Math.sin(e.yaw)*spd,clamp(aim.y*.45,-26,26),-Math.cos(e.yaw)*spd);const bank=clamp(Math.atan2(Math.sin(heading-e.yaw),Math.cos(heading-e.yaw)),-.7,.7);e.mesh.rotation.set(clamp(e.velocity.y/spd,-.3,.3),e.yaw,bank,'YXZ');if(e.mesh.userData.prop)e.mesh.userData.prop.rotation.z+=dt*50;if(e.shoot<=0&&dist<850){e.shoot=rand(2.8,4.5)/(1+this.wave*.06);const attack=pp.clone().addScaledVector(this.getForward(),this.speed*dist/900).sub(p).normalize();this.addBullet(p.clone(),attack,true,e.type===2?22:13);if(e.type===2)this.addBullet(p.clone().add(new V(9,0,0)),attack,true,16);}}p.addScaledVector(e.velocity,dt);p.y=clamp(p.y,70,500);if(dist<e.radius+9){this.damage(e.type===3?35:25);p.addScaledVector(delta.normalize(),-30);}if(e.mesh.userData.paint)e.mesh.userData.paint.emissive.setHex(e.hit?0xff7b3b:0);}
 for(let i=this.enemies.length-1;i>=0;i--)if(this.enemies[i].hp<=0){const e=this.enemies[i];this.scene.remove(e.mesh);this.disposePlane(e.mesh);this.enemies.splice(i,1);}}
 tickBullets(dt){for(let i=this.bullets.length-1;i>=0;i--){const b=this.bullets[i];b.old.copy(b.mesh.position);b.life-=dt;b.age+=dt;if(b.missile&&b.target?.hp>0&&this.enemies.includes(b.target)){const direction=b.target.mesh.position.clone().sub(b.mesh.position).normalize();b.velocity.lerp(direction.multiplyScalar(340),1-Math.exp(-dt*4));if(Math.random()<.5)this.trail(b.mesh.position.clone(),0xfce5bd);}b.mesh.position.addScaledVector(b.velocity,dt);b.mesh.quaternion.setFromUnitVectors(this.up,b.velocity.clone().normalize());const segment=new THREE.Line3(b.old,b.mesh.position);const near=new V();if(b.enemy){segment.closestPointToPoint(this.player.position,true,near);if(near.distanceTo(this.player.position)<8){this.damage(b.damage);b.life=0;}}else{for(const e of this.enemies){if(e.hp<=0)continue;segment.closestPointToPoint(e.mesh.position,true,near);if(near.distanceTo(e.mesh.position)<e.radius){this.hitEnemy(e,b.damage,b.missile);b.life=0;break;}}}if(b.life<=0){this.scene.remove(b.mesh);b.mesh.geometry.dispose();b.mesh.material.dispose();this.bullets.splice(i,1);}}}
 tickPickups(dt){for(let i=this.pickups.length-1;i>=0;i--){const b=this.pickups[i];b.life-=dt;b.mesh.rotation.y+=dt*1.8;b.mesh.rotation.z+=dt;const d=this.player.position.clone().sub(b.mesh.position),dist=d.length();if(dist<105)b.mesh.position.addScaledVector(d.normalize(),dt*(140-dist));if(dist<22){if(b.type==='health')this.hp=Math.min(this.maxHp,this.hp+28);if(b.type==='missile')this.missiles+=2;if(b.type==='shield')this.shield=Math.min(this.maxShield,this.shield+30);this.audio.play('pickup');this.emit('toast',{text:{health:'维修补给 · 生命 +28',missile:'武器补给 · 导弹 +2',shield:'能量补给 · 护盾 +30'}[b.type]});b.life=0;}if(b.life<=0){this.scene.remove(b.mesh);b.mesh.geometry.dispose();b.mesh.material.dispose();this.pickups.splice(i,1);}}
 for(let i=this.rings.length-1;i>=0;i--){const r=this.rings[i];r.mesh.rotation.z+=dt*.4;if(this.player.position.distanceTo(r.mesh.position)<30){this.ringTotal++;this.waveRings++;this.score+=150;this.runCoins+=15;this.boost=100;this.audio.play('pickup');this.emit('toast',{text:this.waveRings===3?'航线挑战完成！+450 分':'穿越航线环 · +150 分 · 加速充满'});if(this.waveRings===3){this.score+=450;this.missiles+=2;}this.scene.remove(r.mesh);r.mesh.geometry.dispose();r.mesh.material.dispose();this.rings.splice(i,1);}}}
 tickParticles(dt){for(let i=this.particles.length-1;i>=0;i--){const p=this.particles[i];p.life-=dt;p.mesh.position.addScaledVector(p.velocity,dt);p.velocity.y-=dt*20;p.mesh.material.opacity=Math.max(0,p.life/p.max);p.mesh.scale.multiplyScalar(1+dt*.3);if(p.life<=0){this.scene.remove(p.mesh);p.mesh.material.dispose();this.particles.splice(i,1);}}}
 tickMenu(dt){this.menuTime+=dt;const t=this.menuTime;this.player.visible=true;this.player.scale.setScalar(innerWidth<700?1.05:1.45);this.player.position.set(10,125+Math.sin(t*.8)*1.8,-60);this.player.rotation.set(.025,Math.PI*1.12+Math.sin(t*.13)*.08,Math.sin(t*.5)*.035);this.player.userData.prop.rotation.z+=dt*45;if(this.player.userData.scarf)this.player.userData.scarf.rotation.x=Math.sin(t*14)*.1;const mobile=innerWidth<700;const pos=mobile?new V(52,151,10):new V(76,159,15);this.camera.position.copy(pos);this.camera.fov=mobile?57:48;this.camera.updateProjectionMatrix();const target=mobile?new V(8,114,-64):new V(-13,123,-48);this.camera.lookAt(target);this.audio.update(false,false);}
 tick(dt){this.time+=dt;this.sea.material.uniforms.uTime.value=this.time;for(const c of this.clouds)c.position.x+=dt*2;if(this.mode==='menu')this.tickMenu(dt);if(this.mode==='playing'){this.runTime+=dt;this.comboTimer=Math.max(0,this.comboTimer-dt);if(!this.comboTimer)this.combo=0;this.tickPlayer(dt);if(this.mode!=='playing')return;this.tickEnemies(dt);this.tickBullets(dt);this.tickPickups(dt);this.tickParticles(dt);this.bannerTimer=Math.max(0,this.bannerTimer-dt);const finished=this.waveBoss?!this.enemies.some(e=>e.type===3&&e.hp>0):this.enemies.every(e=>e.hp<=0);if(finished&&this.mode==='playing'){this.transition+=dt;if(this.transition>1.8){if(this.wave%5===0&&!this.endless)this.finish(true);else{this.mode='upgrade';this.clearInput();const choices=[...UPGRADES].sort(()=>Math.random()-.5).slice(0,3);this.emit('upgrade',{choices,wave:this.wave});}}}else this.transition=0;}else if(this.mode==='gameover')this.tickParticles(dt);if(this.mode!=='playing'&&this.mode!=='menu')this.audio.update(false,false);}
 loop(){requestAnimationFrame(()=>this.loop());const dt=Math.min(this.clock.getDelta(),.04);this.tick(dt);this.renderer.render(this.scene,this.camera);this.emit('frame');}
 state(){return{mode:this.mode,aircraft:AIRCRAFT[this.selected].name,difficulty:this.difficulty||'adventure',wave:this.wave||0,score:this.score||0,hp:Math.round(this.hp||0),shield:Math.round(this.shield||0),enemies:this.enemies.length,missiles:this.missiles||0,rings:this.ringTotal||0,autoFire:this.autoFire,control:this.control};}
}
